INSERT INTO `site_settings` VALUES (1,'contact_email','gohc2026@gmail.com','text','contact','Contact Email','2026-08-19 04:16:38','2026-08-19 04:16:38'),(2,'contact_phone','+91 9789582404','text','contact','Contact Phone 1','2026-08-19 04:16:38','2026-10-07 01:50:26'),(3,'contact_address','Madras Christian College, Tambaram, Chennai','text','contact','Address','2026-08-19 04:16:38','2026-08-19 04:16:38'),(4,'topbar_format','Online | In-person','text','contact','Event Format (Topbar)','2026-08-19 04:16:38','2026-08-19 04:16:38'),(5,'hero_title','GLOBAL ONE HEALTH CONFLUENCE  2026','textarea','hero','Main Heading','2026-08-19 04:16:38','2026-10-05 01:01:11'),(6,'hero_subtitle','Bridging Microbes, Molecules & Mankind for Sustainability','text','hero','Subtitle','2026-08-19 04:16:38','2026-08-19 04:16:38'),(7,'hero_organized_by','Jointly organized by Department of Microbiology & Department of Chemistry (SFS), Madras Christian College','text','hero','Organized By','2026-08-19 04:16:38','2026-10-05 01:01:11'),(8,'hero_dates','21st and 22nd December 2026','text','hero','Event Dates','2026-08-19 04:16:38','2026-10-05 01:01:11'),(9,'hero_location','Madras Christian College, Chennai','text','hero','Event Location','2026-08-19 04:16:38','2026-08-19 04:16:38'),(10,'about_conference','The Global One Health Confluence 2026 is envisioned as a flagship international interdisciplinary forum that brings together leading scientists, academicians, clinicians, policymakers, industry leaders, innovators, entrepreneurs, and students to address emerging global health challenges through the One Health framework.\n\nRecognizing the intricate interdependence between human health, animal health, environmental sustainability, and technological innovation, the conference seeks to foster scientific dialogue, collaborative research, translational innovation, and policy engagement. The event aligns with the United Nations Sustainable Development Goals (SDGs) and India\'s vision of promoting sustainable, inclusive, and evidence-based solutions for future health security.\n\nOrganized by the Departments of Microbiology and Chemistry (SFS), Madras Christian College, in collaboration with reputed national and international institutions, professional societies, research organizations, healthcare institutions, and industry partners, this confluence will serve as a premier platform for knowledge exchange, interdisciplinary networking, innovation showcasing, and strategic collaborations.','textarea','about','About Conference','2026-08-19 04:16:38','2026-08-19 04:16:38'),(11,'about_mission','To connect researchers, thought leaders, and institutions through impactful events that inspire knowledge-sharing and real-world solutions.','textarea','about','Our Mission','2026-08-19 04:16:38','2026-08-19 04:16:38'),(12,'about_vision','To build a global platform that showcases research, fosters collaboration, and drives innovation across disciplines.','textarea','about','Our Vision','2026-08-19 04:16:38','2026-08-19 04:16:38'),(13,'about_mcc','Madras Christian College (MCC) is one of India’s premier educational institutions, founded by Scottish missionaries in 1837. Over the years, it has evolved into an institution committed to academic excellence, spiritual vitality, and social relevance.\n\nIn 2018, MCC was re-accredited by NAAC with an \'A\' Grade and ranks 14th in the NIRF rankings, reflecting its high academic standards, robust research output, and unwavering dedication to quality education.\n\nMCC established the MCC Boyd-Tandon School of Business in 2016 with the vision of providing world-class business education. The Centre for Computational Informatics serves as a research hub dedicated to advancing computational science through cutting-edge research, impactful collaborations, and hands-on training.\n\nTo further strengthen innovation and entrepreneurship, MCC launched the Institution’s Innovation Council in 2020 and the MCC-MRF Innovation Park (MMIP) in 2021. These initiatives foster advanced research, support innovation-driven startups, and nurture the next generation of entrepreneurs.','textarea','about','About Madras Christian College','2026-08-19 04:16:38','2026-08-19 22:54:34'),(14,'about_dept','The Department of Microbiology at Madras Christian College (MCC) was established in 2002 and has earned recognition for its academic excellence, leadership development, and commitment to research and social relevance.\n\nThe department offers a dynamic curriculum designed to equip students with the knowledge and skills required to explore emerging opportunities in the field of Microbiology, preparing them for both research and industry careers.\n\nSince 2018, the department has been a full-fledged research unit offering Ph.D. programmes in Microbiology and Applied Microbiology. Research activities span diverse disciplines within Microbiology, including areas aligned with the conference themes and emerging scientific developments.\n\nThe department is widely recognized for its strong industry-academia collaborations, faculty and student-driven innovations, active research contributions, and a culture that encourages intellectual property creation and patent development.','textarea','about','About Department of Microbiology','2026-08-19 04:16:38','2026-10-05 01:01:11'),(15,'mcc_stat1_title','1837','text','about','MCC Stat 1 (Title)','2026-08-19 04:16:38','2026-08-19 04:16:38'),(16,'mcc_stat1_sub','Founded In','text','about','MCC Stat 1 (Subtitle)','2026-08-19 04:16:38','2026-08-19 04:16:38'),(17,'mcc_stat2_title','\'A\' Grade','text','about','MCC Stat 2 (Title)','2026-08-19 04:16:38','2026-08-19 22:54:34'),(18,'mcc_stat2_sub','NAAC Accredited','text','about','MCC Stat 2 (Subtitle)','2026-08-19 04:16:38','2026-08-19 04:16:38'),(19,'mcc_stat3_title','Rank 14','text','about','MCC Stat 3 (Title)','2026-08-19 04:16:38','2026-08-19 04:16:38'),(20,'mcc_stat3_sub','NIRF Rankings','text','about','MCC Stat 3 (Subtitle)','2026-08-19 04:16:38','2026-08-19 04:16:38'),(21,'about_simats','Saveetha Institute of Medical and Technical Sciences (SIMATS) is a prestigious Deemed-to-be-University located in Chennai, Tamil Nadu. Established in 2005, SIMATS has rapidly grown into a premier multidisciplinary institution offering high-quality education and research across Medicine, Dentistry, Engineering, Law, and Allied Health Sciences.\n\nSIMATS is accredited by NAAC with the highest \'A++\' Grade, signifying its world-class teaching standards, state-of-the-art infrastructure, and strong emphasis on research and development. The university ranks 11th in the \'University\' category under the National Institutional Ranking Framework (NIRF) in 2024.\n\nWith a focus on innovation and clinical excellence, SIMATS hosts advanced simulation labs, comprehensive research centers, and maintains active collaborations with top international institutions and industry leaders globally.','textarea','about','About SIMATS','2026-08-19 04:16:38','2026-08-19 04:16:38'),(22,'simats_stat1_title','2005','text','about','SIMATS Stat 1 (Title)','2026-08-19 04:16:38','2026-08-19 04:16:38'),(23,'simats_stat1_sub','Established','text','about','SIMATS Stat 1 (Subtitle)','2026-08-19 04:16:38','2026-08-19 04:16:38'),(24,'simats_stat2_title','\'A++\' Grade','text','about','SIMATS Stat 2 (Title)','2026-08-19 04:16:38','2026-08-19 04:16:38'),(25,'simats_stat2_sub','NAAC Accredited','text','about','SIMATS Stat 2 (Subtitle)','2026-08-19 04:16:38','2026-08-19 04:16:38'),(26,'simats_stat3_title','Rank 11','text','about','SIMATS Stat 3 (Title)','2026-08-19 04:16:38','2026-08-19 04:16:38'),(27,'simats_stat3_sub','NIRF University','text','about','SIMATS Stat 3 (Subtitle)','2026-08-19 04:16:38','2026-08-19 04:16:38'),(28,'about_chemistry','The Department of Chemistry (Self-Financed Stream - SFS) at Madras Christian College (MCC) was established in 2003 to provide comprehensive and industry-relevant chemical education. The department offers a highly sought-after M.Sc. in Chemistry program designed to bridge theoretical concepts with experimental application.\n\nThe curriculum is structured around modern developments in chemical sciences, covering advanced organic, inorganic, physical, analytical, and environmental chemistry. With well-equipped dedicated laboratories and independent research infrastructure, students are exposed to hands-on training and advanced analytical instrumentation.\n\nTo prepare students for professional success, the department fosters collaborations with national research laboratories and leading pharmaceutical and chemical industries, enabling students to undertake high-impact academic projects and internship opportunities.','textarea','about','About Department of Chemistry (SFS)','2026-08-19 04:16:38','2026-10-05 01:01:11'),(29,'participants_desc','Join the confluence to bridge microbes, molecules & mankind for a sustainable future.','textarea','participants','Section Description','2026-08-19 04:16:38','2026-08-19 04:16:38'),(30,'participant_1','Students &\nResearch Scholars','textarea','participants','Participant Type 1','2026-08-19 04:16:38','2026-08-19 04:16:38'),(31,'participant_2','Academicians &\nPolicy Makers','textarea','participants','Participant Type 2','2026-08-19 04:16:38','2026-08-19 04:16:38'),(32,'participant_3','Research\nScientists','textarea','participants','Participant Type 3','2026-08-19 04:16:38','2026-08-19 04:16:38'),(33,'participant_4','Health\nProfessionals','text','participants','Participant Type 4','2026-08-19 04:16:38','2026-08-19 04:16:38'),(34,'participant_5','Industry Experts\n(Pharma & Health)','text','participants','Participant Type 5','2026-08-19 04:16:38','2026-08-19 04:16:38'),(35,'workshop_title','Hands-On Metagenomics','text','workshop','Main Title','2026-08-19 04:16:38','2026-08-19 04:16:38'),(36,'workshop_desc','Join us for an exclusive one-day hands-on workshop on the day before the main conference. Participants will gain practical skills in metagenomic data analysis—from quality control and community profiling to assembly and visualization using tools like QIIME2 and relevant datasets.\n\nPerfect for students, researchers, and faculty looking to strengthen their bioinformatics toolkit.','textarea','workshop','Description','2026-08-19 04:16:38','2026-08-19 04:16:38'),(37,'workshop_f1_title','Practical Skills','text','workshop','Feature 1 Title','2026-08-19 04:16:38','2026-08-19 04:16:38'),(38,'workshop_f1_desc','Learn quality control, community profiling, and assembly.','text','workshop','Feature 1 Description','2026-08-19 04:16:38','2026-08-19 04:16:38'),(39,'workshop_f2_title','Industry Tools','text','workshop','Feature 2 Title','2026-08-19 04:16:38','2026-08-19 04:16:38'),(40,'workshop_f2_desc','Hands-on visualization using tools like QIIME2 and real datasets.','text','workshop','Feature 2 Description','2026-08-19 04:16:38','2026-08-19 04:16:38'),(41,'workshop_f3_title','Bioinformatics Toolkit','text','workshop','Feature 3 Title','2026-08-19 04:16:38','2026-08-19 04:16:38'),(42,'workshop_f3_desc','Designed specifically for students, researchers, and faculty.','text','workshop','Feature 3 Description','2026-08-19 04:16:38','2026-08-19 04:16:38'),(43,'thrust_areas_desc','Explore the latest advancements, critical challenges, and future innovations across our core diagnostic and scientific themes.','textarea','thrust_areas','Section Description','2026-08-19 04:16:38','2026-08-19 04:16:38'),(44,'thrust_1','Artificial intelligence in infectious disease diagnostics','text','thrust_areas','Theme 1','2026-08-19 04:16:38','2026-08-19 04:16:38'),(45,'thrust_2','AI in diagnostic microbiology','text','thrust_areas','Theme 2','2026-08-19 04:16:38','2026-08-19 04:16:38'),(46,'thrust_3','Molecular diagnostics and genomics','text','thrust_areas','Theme 3','2026-08-19 04:16:38','2026-08-19 04:16:38'),(47,'thrust_4','Digital health and intelligent systems','text','thrust_areas','Theme 4','2026-08-19 04:16:38','2026-08-19 04:16:38'),(48,'thrust_5','Clinical applications and future directions','text','thrust_areas','Theme 5','2026-08-19 04:16:38','2026-08-19 04:16:38'),(49,'thrust_6','Antimicrobial resistance and rapid detection','text','thrust_areas','Theme 6','2026-08-19 04:16:38','2026-08-19 04:16:38'),(50,'thrust_7','Emerging infectious diseases','text','thrust_areas','Theme 7','2026-08-19 04:16:38','2026-08-19 04:16:38'),(51,'thrust_8','Point-of-care diagnostics','text','thrust_areas','Theme 8','2026-08-19 04:16:38','2026-08-19 04:16:38'),(52,'thrust_9','Clinical case studies','text','thrust_areas','Theme 9','2026-08-19 04:16:38','2026-08-19 04:16:38'),(53,'abstract_desc_1','Abstracts are invited for original research work that has not been published or submitted elsewhere.','textarea','abstract','Description Paragraph 1','2026-08-19 04:16:38','2026-08-19 04:16:38'),(54,'abstract_desc_2','Students, research scholars, faculty members, and industry participants may submit abstracts for <strong>oral and/or poster presentations</strong>.','textarea','abstract','Description Paragraph 2','2026-08-19 04:16:38','2026-08-19 04:16:38'),(55,'abstract_req_font','Times New Roman, Size 12','text','abstract','Font Requirement','2026-08-19 04:16:38','2026-08-19 04:16:38'),(56,'abstract_req_spacing','1.5 line spacing','text','abstract','Spacing Requirement','2026-08-19 04:16:38','2026-08-19 04:16:38'),(57,'abstract_req_length','Maximum of 250 words','text','abstract','Length Requirement','2026-08-19 04:16:38','2026-08-19 04:16:38'),(58,'abstract_req_keywords','Maximum of 5 keywords','text','abstract','Keywords Requirement','2026-08-19 04:16:38','2026-08-19 04:16:38'),(59,'awards_desc','To recognize outstanding research contributions, we are proud to present awards for the most exceptional presentations at the summit.','textarea','awards','Description','2026-08-19 04:16:38','2026-08-19 04:16:38'),(60,'awards_oral_title','Best Oral Presentation','text','awards','Oral Award Title','2026-08-19 04:16:38','2026-08-19 04:16:38'),(61,'awards_oral_desc','Awarded to the most impactful and articulate oral research presentation.','text','awards','Oral Award Description','2026-08-19 04:16:38','2026-08-19 04:16:38'),(62,'awards_poster_title','Best Poster Award','text','awards','Poster Award Title','2026-08-19 04:16:38','2026-08-19 04:16:38'),(63,'awards_poster_desc','Awarded for outstanding visual communication and scientific clarity.','text','awards','Poster Award Description','2026-08-19 04:16:38','2026-08-19 04:16:38'),(64,'venue_discover_title','Discover Madras Christian College','text','venue','Discover Title','2026-08-19 04:16:38','2026-08-19 04:16:38'),(65,'venue_discover_text','Founded in 1837, Madras Christian College (MCC) is one of Asia\'s oldest and most prestigious academic institutions. Set within a sprawling, lush 320-acre scrub jungle campus in Tambaram, Chennai, MCC offers a serene, intellectually stimulating environment that provides a perfect backdrop for international conferences, global collaboration, and cutting-edge scientific exchange.','textarea','venue','Discover Text','2026-08-19 04:16:38','2026-08-19 04:16:38'),(66,'venue_heritage_title','A Hub of Heritage & Innovation','text','venue','Heritage Title','2026-08-19 04:16:38','2026-08-19 04:16:38'),(67,'venue_heritage_text','MCC seamlessly blends a rich historical legacy with modern scientific inquiry. With a profound history of producing renowned scholars, researchers, and global leaders, the institution continues to foster excellence. Its proximity to prominent research hubs in Chennai and its own state-of-the-art facilities make it an ideal meeting point for the BioMed Summit 2027.','textarea','venue','Heritage Text','2026-08-19 04:16:38','2026-08-19 04:16:38'),(68,'venue_biodiversity_title','Campus Biodiversity & Environment','text','venue','Biodiversity Title','2026-08-19 04:16:38','2026-08-19 04:16:38'),(69,'venue_biodiversity_text','The MCC campus is a documented sanctuary of rare flora and fauna, providing delegates with a refreshing escape from the urban hustle. During the conference, attendees can enjoy:','textarea','venue','Biodiversity Text','2026-08-19 04:16:38','2026-08-19 04:16:38'),(70,'venue_biodiversity_list','Exploring the expansive, protected scrub jungle ecosystem\nHistoric British-era architectural landmarks seamlessly integrated with modern halls\nA tranquil, pollution-free atmosphere ideal for focused scientific networking\nThe vibrant cultural heritage and traditional South Indian hospitality of Chennai','textarea','venue','Biodiversity Bullets (One per line)','2026-08-19 04:16:38','2026-08-19 04:16:38'),(71,'venue_accessibility_title','Easy Accessibility','text','venue','Accessibility Title','2026-08-19 04:16:38','2026-08-19 04:16:38'),(72,'venue_accessibility_text','Located in the bustling metropolis of Chennai, MCC is exceptionally well-connected. It is easily accessible via the Chennai International Airport (MAA), which offers direct flights worldwide. Furthermore, the Tambaram Railway Station and major transit hubs are situated directly opposite the campus, ensuring seamless domestic and international travel for all delegates.','textarea','venue','Accessibility Text','2026-08-19 04:16:38','2026-08-19 04:16:38'),(73,'venue_facilities_title','World-Class Conference Facilities','text','venue','Facilities Title','2026-08-19 04:16:38','2026-08-19 04:16:38'),(74,'venue_facilities_text','MCC boasts a wide array of premium venues, including historic grand auditoriums and highly equipped modern smart-halls. With advanced audio-visual technology, high-speed connectivity, and spacious seating, the campus provides a highly professional, comfortable, and accommodating environment for large-scale plenary sessions and specialized workshops alike.','textarea','venue','Facilities Text','2026-08-19 04:16:38','2026-08-19 04:16:38'),(75,'awards_intro','At Biomed Summit, we celebrate the spirit of research, innovation, and academic excellence. To foster advancement and honor exceptional contributions, we proudly present the Conference Awards to outstanding researchers, scholars, and innovators.','textarea','awards_page','Intro Paragraph','2026-08-19 04:16:38','2026-08-19 04:16:38'),(76,'sponsors_intro','Partnering with us as a sponsor or exhibitor gives your organization a unique opportunity to stand at the forefront of global innovation. Our international summits connect you directly with leading researchers, decision-makers, and industry pioneers — offering high-value visibility, strategic networking, and brand credibility. From showcasing your latest innovations to forging meaningful collaborations, this is your chance to amplify your impact, generate quality leads, and position your brand where the future is being shaped.','textarea','sponsors','Intro Paragraph','2026-08-19 04:16:38','2026-08-19 04:16:38'),(77,'sponsors_benefits','Enhance your brand visibility among international audiences\nShowcase your technologies, products, or services to leading institutions and professionals\nConnect directly with key decision-makers and industry influencers\nBuild global partnerships and collaborative networks\nParticipate in high-value networking sessions, panels, and technical discussions\nReceive branding across digital, print, and on-site materials\nGenerate qualified leads and accelerate business development\nEstablish your brand as a thought leader in your industry','textarea','sponsors','Key Benefits','2026-08-19 04:16:38','2026-08-19 04:16:38'),(78,'hero_bg_image','images/hero-bg.png','image','hero','Hero Background Image','2026-08-19 06:27:37','2026-08-19 06:27:37'),(79,'objectives_desc','The Global One Health Confluence 2026 brings together leaders in science, policy, and practice to address our most pressing health challenges through a unified interdisciplinary approach.','textarea','objectives','Section Description','2026-08-19 06:31:24','2026-08-19 06:31:24'),(80,'obj_1_title','Promote Interdisciplinary Collaboration','text','objectives','Objective 1 Title','2026-08-19 06:31:24','2026-10-05 01:01:11'),(81,'obj_1_desc','To promote interdisciplinary collaboration across microbiology, health and sustainability.','textarea','objectives','Objective 1 Description','2026-08-19 06:31:24','2026-10-05 01:01:11'),(82,'obj_2_title','Discuss Emerging Challenges','text','objectives','Objective 2 Title','2026-08-19 06:31:24','2026-10-05 01:01:11'),(83,'obj_2_desc','To discuss emerging challenges and innovative solutions through global scientific discourse.','textarea','objectives','Objective 2 Description','2026-08-19 06:31:24','2026-10-05 01:01:11'),(84,'obj_3_title','Encourage Research Translation','text','objectives','Objective 3 Title','2026-08-19 06:31:24','2026-10-05 01:01:11'),(85,'obj_3_desc','To encourage research translation for real-world applications and impact.','textarea','objectives','Objective 3 Description','2026-08-19 06:31:24','2026-10-05 01:01:11'),(86,'obj_4_title','Foster Global Partnerships','text','objectives','Objective 4 Title','2026-08-19 06:31:24','2026-10-05 01:01:11'),(87,'obj_4_desc','To foster global partnerships for a One Health and sustainable future.','textarea','objectives','Objective 4 Description','2026-08-19 06:31:24','2026-10-05 01:01:11'),(88,'pillars_title','Five Pillars of the Confluence','text','pillars','Section Title','2026-08-19 06:39:07','2026-08-19 06:39:07'),(89,'pillars_subtitle','Interdisciplinary framework driving sustainable global health through science, policy & partnership','textarea','pillars','Section Subtitle','2026-08-19 06:39:07','2026-08-19 06:39:07'),(90,'pillar_1_tag','Research','text','pillars','Pillar 1 Tag','2026-08-19 06:39:07','2026-08-19 06:39:07'),(91,'pillar_1_title','Scientific Excellence','text','pillars','Pillar 1 Title','2026-08-19 06:39:07','2026-08-19 06:39:07'),(92,'pillar_1_desc','Facilitating high-quality interdisciplinary scientific discourse spanning microbiology, chemistry, biotechnology, environmental sciences, public health, and molecular medicine.','textarea','pillars','Pillar 1 Description','2026-08-19 06:39:07','2026-08-19 06:39:07'),(93,'pillar_1_icon','fa-solid fa-microscope','text','pillars','Pillar 1 Icon','2026-08-19 06:39:07','2026-10-05 01:01:11'),(94,'pillar_2_tag','Innovation','text','pillars','Pillar 2 Tag','2026-08-19 06:39:07','2026-08-19 06:39:07'),(95,'pillar_2_title','Translational Innovation','text','pillars','Pillar 2 Title','2026-08-19 06:39:07','2026-08-19 06:39:07'),(96,'pillar_2_desc','Promoting research translation through biotechnology, diagnostics, biosensors, sustainable chemistry, advanced materials, green technologies, and circular bioeconomy.','textarea','pillars','Pillar 2 Description','2026-08-19 06:39:07','2026-08-19 06:39:07'),(97,'pillar_2_icon','fa-solid fa-flask-vial','text','pillars','Pillar 2 Icon','2026-08-19 06:39:07','2026-08-19 06:39:07'),(98,'pillar_3_tag','Policy','text','pillars','Pillar 3 Tag','2026-08-19 06:39:07','2026-08-19 06:39:07'),(99,'pillar_3_title','Policy & Governance','text','pillars','Pillar 3 Title','2026-08-19 06:39:07','2026-08-19 06:39:07'),(100,'pillar_3_desc','Strengthening dialogue among researchers, policymakers, governmental agencies, and international organizations for evidence-informed health governance.','textarea','pillars','Pillar 3 Description','2026-08-19 06:39:07','2026-08-19 06:39:07'),(101,'pillar_3_icon','fa-solid fa-scale-balanced','text','pillars','Pillar 3 Icon','2026-08-19 06:39:07','2026-08-19 06:39:07'),(102,'pillar_4_tag','Heritage','text','pillars','Pillar 4 Tag','2026-08-19 06:39:07','2026-08-19 06:39:07'),(103,'pillar_4_title','Indigenous Integration','text','pillars','Pillar 4 Title','2026-08-19 06:39:07','2026-08-19 06:39:07'),(104,'pillar_4_desc','Exploring the role of Indian Knowledge Systems and traditional healthcare practices in complementing modern One Health approaches.','textarea','pillars','Pillar 4 Description','2026-08-19 06:39:07','2026-08-19 06:39:07'),(105,'pillar_4_icon','fa-solid fa-leaf','text','pillars','Pillar 4 Icon','2026-08-19 06:39:07','2026-08-19 06:39:07'),(106,'pillar_5_tag','Network','text','pillars','Pillar 5 Tag','2026-08-19 06:39:07','2026-08-19 06:39:07'),(107,'pillar_5_title','Global Partnerships','text','pillars','Pillar 5 Title','2026-08-19 06:39:07','2026-08-19 06:39:07'),(108,'pillar_5_desc','Building long-term collaborative networks among academia, healthcare, industry, research institutions, and international organizations.','textarea','pillars','Pillar 5 Description','2026-08-19 06:39:07','2026-08-19 06:39:07'),(109,'pillar_5_icon','fa-solid fa-earth-americas','text','pillars','Pillar 5 Icon','2026-08-19 06:39:07','2026-08-19 06:39:07'),(110,'hero_btn1_text','REGISTER NOW','text','hero','Primary Button Text','2026-08-19 23:26:45','2026-08-19 23:29:16'),(111,'hero_btn1_link','/registration','text','hero','Primary Button Link','2026-08-19 23:26:45','2026-08-19 23:29:16'),(112,'hero_btn2_text','APPLY FOR AWARDS','text','hero','Secondary Button Text','2026-08-19 23:26:45','2026-10-06 06:43:26'),(113,'hero_btn2_link','/awards','text','hero','Secondary Button Link','2026-08-19 23:26:45','2026-10-06 06:43:26'),(114,'obj_5_title','Knowledge Exchange','text','objectives','Objective 5 Title','2026-09-02 23:44:45','2026-09-07 05:05:39'),(115,'obj_5_desc','Provide a platform for knowledge exchange and networking, empowering researchers, students and innovators to showcase impactful research.','textarea','objectives','Objective 5 Description','2026-09-02 23:44:45','2026-09-02 23:44:45'),(116,'org_section_subtitle','About The Organizers','text','about_organizer','Section Subtitle','2026-09-07 04:18:03','2026-09-07 04:18:03'),(117,'org_section_title','Host Institutions & Departments','text','about_organizer','Section Title','2026-09-07 04:18:03','2026-09-07 04:18:03'),(118,'mcc_tab_title','Madras Christian College','text','about_organizer','MCC Tab Nav Title','2026-09-07 04:18:03','2026-09-07 04:18:03'),(119,'mcc_tab_sub','MCC • Chennai','text','about_organizer','MCC Tab Nav Subtitle','2026-09-07 04:18:03','2026-09-07 04:18:03'),(120,'mcc_tag','Madras Christian College','text','about_organizer','MCC Tagline','2026-09-07 04:18:03','2026-09-07 04:18:03'),(121,'mcc_title','A Legacy of Academic Excellence','text','about_organizer','MCC Title','2026-09-07 04:18:03','2026-09-07 04:18:03'),(122,'mcc_p1','Madras Christian College (MCC), established in 1837, is one of India\'s premier institutions of higher learning with a rich heritage of academic excellence, character formation and nation building.','textarea','about_organizer','MCC Paragraph 1','2026-09-07 04:18:03','2026-09-07 04:18:03'),(123,'mcc_p2','Affiliated to the University of Madras and accredited with \'A\' Grade by NAAC, MCC offers a vibrant environment for holistic education across disciplines.','textarea','about_organizer','MCC Paragraph 2','2026-09-07 04:18:03','2026-09-07 04:18:03'),(124,'mcc_p3','The Department of Microbiology at MCC has a strong legacy of quality teaching, innovative research and contributions to the advancement of microbial sciences with a focus on societal impact and global relevance.','textarea','about_organizer','MCC Paragraph 3','2026-09-07 04:18:03','2026-09-07 04:18:03'),(125,'mcc_feat1_title','ESTABLISHED IN 1837','text','about_organizer','Highlight 1 Title','2026-09-07 04:18:03','2026-09-07 04:18:03'),(126,'mcc_feat1_sub','A legacy of 189 years of academic excellence','text','about_organizer','Highlight 1 Subtitle','2026-09-07 04:18:03','2026-09-07 04:18:03'),(127,'mcc_feat1_icon','fa-solid fa-landmark','text','about_organizer','Highlight 1 Icon','2026-09-07 04:18:03','2026-09-07 04:18:03'),(128,'mcc_feat2_title','\'A\' GRADE BY NAAC','text','about_organizer','Highlight 2 Title','2026-09-07 04:18:03','2026-09-07 04:18:03'),(129,'mcc_feat2_sub','Recognized for quality and institutional excellence','text','about_organizer','Highlight 2 Subtitle','2026-09-07 04:18:03','2026-09-07 04:18:0